var map=new LabPinMap(activeLow:true);
bool rawHigh=true;
bool busy=map.Decode(rawHigh); // false：正確低有效
var c=new LabPttController { Busy=busy };
Console.WriteLine(c.Press(0)); // True
var blocked=new LabPttController { Busy=map.Decode(false) };
Console.WriteLine(blocked.Press(0)); // False

var c=new LabPttController { RequireGrant=true };
c.Press(0); int old=c.Epoch; c.Release(10); c.Press(20);
c.Grant(old,30); // WaitingGrant、Ptt=false
c.Grant(c.Epoch,40); // Keying、Ptt=true、AudioOpen=false
c.Ready(c.Epoch,50); c.Release(60); // Idle
